internal abstract class GUPItemBasePriceCalcJob extends RunBaseBatch
{
    ItemId                      itemId;
    InventDimId                 inventDimId;
    GUPBasePriceVersionId       basePriceVersionId;
    InventSiteId                siteId;
    TransDate                   calcDate;
    GUPBasePriceCalcPriceCalcId priceCalcId;

    GUPBasePriceCalcItem        basePriceCalcItem;
    GUPBasePriceRawData         basePriceRawData;
    boolean                     showItemPriceCalcFormAfterRun;
    QueryRun                    queryRun;

    // Transfer
    NoYes                       purchPriceTransfer;
    NoYes                       salesPriceTransfer;
    NoYes                       costPriceTransfer;

    GUPCalcBasePriceVersionUpdate calcBasePriceVersionUpdate;

    // Where used update
    GUPBasePriceCalcWhereUsedUpdate      basePriceCalcWhereUsedUpdate;

    GUPBasePriceVersion basePriceVersion;

    //Activate price enabled
    GUPBasePriceActivatePrice       basePriceActivatePrice;


    #Define.CurrentVersion(99)
    #LOCALMACRO.CurrentList
        CalcDate,
        purchPriceTransfer,
        costPriceTransfer,
        salesPriceTransfer,
        basePriceVersionId,
        calcBasePriceVersionUpdate,
        siteId,
        basePriceCalcWhereUsedUpdate,
        itemId,
        inventDimId,
        priceCalcId,
        basePriceVersion,
        basePriceActivatePrice
    #ENDMACRO

}

