InventDimId inventDimIdSite()
{
    InventDim   inventDimSite;

    inventDimSite.InventSiteId = this.parmSiteId();
    return InventDim::findOrCreate(inventDimSite).InventDimId;
}

boolean showItem()
{
    return true;
}

void new()
{
    super();

    calcDate                    = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
    costPriceTransfer           = NoYes::Yes;
    purchPriceTransfer          = NoYes::Yes;
    salesPriceTransfer          = NoYes::Yes;
    basePriceVersionId          = '';
    calcBasePriceVersionUpdate  = GUPCalcBasePriceVersionUpdate::Overwrite;

}

public container pack()
{
    container packed = [#CurrentVersion, #CurrentList, queryRun.pack()];

    return packed;
}

public Object dialog()
{
    return this.dialogInternal(Dialog::newFormnameRunbase(formStr(GUPItemBasePriceCalcDialog), this));
}

protected GUPBasePriceCalcItem constructbasePriceCalcItem()
{
    GUPBasePriceCalcItem basePriceCalcItemLocal;

    basePriceCalcItemLocal = GUPBasePriceCalcItem::newItem(
        basePriceRawData,
        itemId,
        inventDimId,
        '',
        calcDate,
        basePriceVersionId,
        calcBasePriceVersionUpdate,
        purchPriceTransfer,
        salesPriceTransfer,
        costPriceTransfer);

    return basePriceCalcItemLocal;
}

void run()
{
    this.runBasePriceCalculation();
}

protected void runBasePriceCalculation()
{
    #OCCRetryCount

    setPrefix(GUPItemBasePriceCalcJob::description());

    try
    {
        ttsbegin;

        basePriceCalcItem = this.constructbasePriceCalcItem();

        if (basePriceCalcItem != null)
        {
            // This will call calculation and infolog on the basePriceCalcItem object
            this.calcBasePriceCalcItem();

            if (basePriceCalcItem.parmBasePriceCalcTable())
            {
                // transfer calculation data to inventItemPrice
                this.updateItemPriceFromCalcData(basePriceCalcItem);
            }
        }

        ttscommit;
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
    catch (Exception::Error)
    {
        if (this.calculateAll())
        {
            throw error(strFmt("@SYS24365", itemId), '', InventTable::infoActionItemId(itemId));
        }
        else
        {
            throw error("@SYS21990");
        }
    }
}

protected void calcBasePriceCalcItem()
{
    basePriceCalcItem.calc();
}

protected void updateItemPriceFromCalcData(GUPBasePriceCalcItem _basePriceCalcItem)
{
    GUPBasePriceCalcUpdateItem basePriceCalcUpdateItem = this.initCalcUpdateItem(_basePriceCalcItem);
    basePriceCalcUpdateItem.run();
}

protected GUPBasePriceCalcUpdateItem initCalcUpdateItem(GUPBasePriceCalcItem _basePriceCalcItem)
{
    GUPBasePriceCalcUpdateItem basePriceCalcUpdateItem = GUPBasePriceCalcUpdateItem::construct();

    basePriceCalcUpdateItem.initFromBuffer(_basePriceCalcItem.parmBasePriceCalcTable());

    basePriceCalcUpdateItem.initParameters(
                                    purchPriceTransfer,
                                    costPriceTransfer,
                                    salesPriceTransfer,
                                    basePriceVersionId,
                                    calcDate);

    return basePriceCalcUpdateItem;
}

boolean calculateAll()
{
    return false;
}

static GUPItemBasePriceCalcJob construct(Args args)
{
    return null;
}

static ClassDescription description()
{
    return "@SYS343262";
}

static void main(Args args)
{
    if (!args)
    {
        throw error(strFmt("@SYS23686", formStr(GUPBasePriceVersion)));
    }

    GUPItemBasePriceCalcJob basePriceCalc = GUPItemBasePriceCalcJob::newBasePriceCalcJobFromArgs(args);

    if (basePriceCalc.prompt())
    {
        using (SysErrorMessageHelpScope scope = SysErrorMessageHelpScope::newErrorContext(args))
        {
            if (basePriceCalc.basePriceActivatePrice == true)
            {
                GUPBasePriceActivationJob  itemBasePriceActivationJob  = GUPBasePriceActivationJob::construct();
                itemBasePriceActivationJob.activePriceJobByVersionId(basePriceCalc.basePriceVersionId);
            }
            basePriceCalc.runOperation();
        }

        basePriceCalc.openItemPriceCalcForm(args.caller());
    }
}

protected void openItemPriceCalcForm(Object _caller)
{
    if (this.parmShowItemPriceCalcFormAfterRun())
    {
        Args argsItemPriceCalcForm = new Args();
        argsItemPriceCalcForm.caller(_caller);
        argsItemPriceCalcForm.record(InventTable::find(this.parmItemId()));

        FormRun formRunItemPriceCalcForm = new MenuFunction(menuitemDisplayStr(GUPItemBasePrice), MenuItemType::Display).create(argsItemPriceCalcForm);
        formRunItemPriceCalcForm.run();
    }
}

public QueryRun queryRun()
{
    return queryRun;
}

public boolean unpack(container packedClass)
{
    container   packedQuery;
    Integer     version;

    version = RunBase::getVersion(packedClass);

    switch (version)
    {
        case #CurrentVersion :
            [version, #CurrentList, packedQuery] = packedClass;

            if (packedQuery)
            {
                queryRun = new QueryRun(packedQuery);
            }
            break;

        default :
            return false;
    }

    return true;
}

static GUPItemBasePriceCalcJob newBasePriceCalcJobFromArgs(Args args)
{
    GUPItemBasePriceCalcJob         basePriceCalc;
    GUPIItemBasePriceCalcIRunnable  calcFormRun;

    calcFormRun = args.caller();
    basePriceCalc = GUPItemBasePriceCalcJob::newAll(calcFormRun.basePriceVersion());

    return basePriceCalc;
}

static GUPItemBasePriceCalcJob newAll(GUPBasePriceVersion _basePriceVersion)
{
    GUPItemBasePriceCalcJob_All  basePriceCalc = GUPItemBasePriceCalcJob_All::construct();

    basePriceCalc.getLast();
    basePriceCalc.parmBasePriceVersionId(_basePriceVersion.VersionId);
    basePriceCalc.parmSiteId(_basePriceVersion.InventSiteId);
    basePriceCalc.parmInventDimId(basePriceCalc.inventDimIdSite());

    return basePriceCalc;
}
